import{_ as t,o,c as n,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/76-尽可能使安全感日渐稳固.md","filePath":"books/attached/76-尽可能使安全感日渐稳固.md","lastUpdated":1794316978000}'),r={name:"books/attached/76-尽可能使安全感日渐稳固.md"};function d(i,a,_,l,c,p){return o(),n("div",null,[...a[0]||(a[0]=[e("h3",{id:"尽可能使安全感日渐稳固",tabindex:"-1"},[s("尽可能使安全感日渐稳固 "),e("a",{class:"header-anchor",href:"#尽可能使安全感日渐稳固","aria-label":'Permalink to "尽可能使安全感日渐稳固"'},"​")],-1),e("p",null,"别忘了依恋风格虽然稳定，但也是可塑的，因此安全感的建立是一个循序渐进的过程。每当新的顾虑、不满和冲突出现时，我们就记录下这条新的信息。这样做能够让我们渐渐打破不安全的范式。但是，安全感的建立不仅仅是解决亲密关系中遇到的问题，也与两人的共同乐趣有关。找到享受二人世界的方式，比如在公园散个步，一场电影或一顿晚餐，看一档两人都喜欢的综艺节目，总之找一种方式让彼此更加贴近对方。只有摆脱非安全型的行为模式，你处理感情问题的能力才会大大提高。苏·约翰森（Sue Johnson）医生，是情绪焦距疗法的提出者，她从多年的临床与写作经验中得出启示：建立关系中的安全感、认识到自己对伴侣有多强的依恋感，非常有利于推进双方的恋爱关系。另一位在依恋理论应用领域的先驱丹尼尔·西格尔（Daniel Siegel）医生在他的很多著作中，例如《心智成长之谜》（Developing Mind）、《从内而外的教养》（Parenting from the Inside Out）以及《第七感》（Mindsight）等等，都提到了有助于人们建立安全感的方法。他通过一种特别的技术，教导那些非安全依恋风格的人如何将从前的经历，以安全的方式解读出来。并让人们知道，小时候原生养育着的记忆，对于依恋风格的有着非常显著的影响。这些知识不仅有助于人们成为合格的父母，同时对生活的其他方面也有很大的推进作用。",-1),e("p",null,"一旦安全感建立，对于亲密关系中的两人就形成双赢局面：焦虑型的一方，可以获得一心渴望的亲密感，而回避型的一方也可以享受到更多独立性，满足自己的需要。",-1)])])}const f=t(r,[["render",d]]);export{m as __pageData,f as default};
